parameters.inputSchema:
{
  "type": "object",
  "required": [
    "isValid",
    "relevanceScore",
    "isDuplicate",
    "duplicateOf",
    "concerns",
    "recommendations",
    "wikipediaValidation",
    "webSearchValidation",
    "domainValidation"
  ],
  "properties": {
    "isValid": {
      "type": "boolean",
      "description": "Whether the actor passes all critical validation checks"
    },
    "relevanceScore": {
      "type": "integer",
      "minimum": 1,
      "maximum": 100,
      "description": "Overall relevance score for adding this actor to the WatchFile"
    },
    "isDuplicate": {
      "type": "boolean",
      "description": "Whether this actor duplicates an existing one"
    },
    "duplicateOf": {
      "type": ["string", "null"],
      "description": "Name of the existing actor this duplicates, if any"
    },
    "concerns": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "List of concerns or issues identified during validation"
    },
    "recommendations": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Actionable recommendations for the user"
    },
    "wikipediaValidation": {
      "type": "object",
      "required": ["found", "summary", "alternativeNames"],
      "additionalProperties": false,
      "properties": {
        "found": {
          "type": "boolean",
          "description": "Whether the actor was found on Wikipedia"
        },
        "summary": {
          "type": "string",
          "description": "Brief summary of what was found about the actor"
        },
        "alternativeNames": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Alternative names, acronyms, or former names found"
        }
      }
    },
    "webSearchValidation": {
      "type": "object",
      "required": ["performed", "sourcesFound", "confirmsExistence", "confirmsActivity", "relevantFindings"],
      "additionalProperties": false,
      "properties": {
        "performed": {
          "type": "boolean",
          "description": "Whether web search was performed for this actor"
        },
        "sourcesFound": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of relevant sources found via web search"
        },
        "confirmsExistence": {
          "type": "boolean",
          "description": "Whether web search confirms the actor exists"
        },
        "confirmsActivity": {
          "type": "boolean",
          "description": "Whether web search confirms the actor is still active (not defunct/merged)"
        },
        "relevantFindings": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Key findings from web search relevant to the WatchFile focus"
        }
      }
    },
    "domainValidation": {
      "type": "object",
      "required": ["exists", "matchesActor", "verificationMethod"],
      "additionalProperties": false,
      "properties": {
        "exists": {
          "type": "boolean",
          "description": "Whether the primaryDomain exists and is reachable"
        },
        "matchesActor": {
          "type": "boolean",
          "description": "Whether the domain content matches the actor identity"
        },
        "verificationMethod": {
          "type": "string",
          "enum": ["whois", "web_search", "direct", "none"],
          "description": "Method used to verify domain ownership"
        }
      }
    }
  },
  "additionalProperties": false
}

